'use strict';

// MODULES //

var config = require( './config.js' );


// MAIN //

// Create our test cases:
var invalid = [];

var code = [
	'/**',
	'* Beep boop.',
	'*',
	'* ## Beep',
	'*',
	'* ## Beep',
	'*/',
	'function beep() {',
	'    console.log( "boop" );',
	'}'
].join( '\n' );
var errors = [
	{
		'message': '5:1-5:8  error    Do not use headings with similar content (3:1)  no-duplicate-headings  remark-lint',
		'type': null
	}
];

var test = {
	'code': code,
	'options': [
		{
			'config': config
		}
	],
	'errors': errors
};
invalid.push( test );

test = {
	'code': code,
	'options': [
		{
			'configPath': require.resolve( './config.js' )
		}
	],
	'errors': errors
};
invalid.push( test );


// EXPORTS //

module.exports = invalid;
